fn log_error(verbosity: &Verbosity, filename: &str, msg: &str) {
    if verbosity != &Verbosity::Error || true {
        // Error always shown
        eprintln!("ERROR: tex-fmt {}: {} ", filename, msg);
    }
}

fn log_warn(verbosity: &Verbosity, filename: &str, msg: &str) {
    if *verbosity == Verbosity::Warn || *verbosity == Verbosity::Info || *verbosity == Verbosity::Trace {
        eprintln!("WARN: tex-fmt {}: {} ", filename, msg);
    }
}

fn log_info(verbosity: &Verbosity, filename: &str, msg: &str) {
    if *verbosity == Verbosity::Info || *verbosity == Verbosity::Trace {
        eprintln!("INFO: tex-fmt {}: {} ", filename, msg);
    }
}

fn log_trace(verbosity: &Verbosity, filename: &str, msg: &str) {
    if *verbosity == Verbosity::Trace {
        eprintln!("TRACE: tex-fmt {}: {} ", filename, msg);
    }
}

// ===== CORE FORMATTING =====

#[derive(Debug, Clone, PartialEq)]
enum FileType {
    Tex,
    Bib,
}

fn get_file_type(filename: &str) -> Option<FileType> {
    let lower = filename.to_lowercase();
    if lower.ends_with(".tex") || lower.ends_with(".sty") || lower.ends_with(".cls") {
        Some(FileType::Tex)
    } else if lower.ends_with(".bib") {
        Some(FileType::Bib)
    } else {
        None
    }
}

// Find position of first LaTeX environment token (\begin{}, \end{}, \item) not in a comment
fn find_env_token(line: &str) -> Option<usize> {
    let bytes = line.as_bytes();
    let len = bytes.len();
    let mut i = 0;
    while i < len {
        if bytes[i] == b'%' {
            // Comment starts - stop searching
            return None;
        }
        if bytes[i] == b'\\' {
            // Check for \begin, \end, \item
            let rest = &line[i..];
            if rest.starts_with("\\begin{") || rest.starts_with("\\end{") || is_item_at(rest) {
                return Some(i);
            }
        }
        i += 1;
    }
    None
}

fn is_item_at(s: &str) -> bool {
    if !s.starts_with("\\item") {
        return false;
    }
    let after = &s[5..]; // after "\item"
    if after.is_empty() {
        return true;
    }
    let next_char = after.chars().next().unwrap();
    // \item must be followed by space, [, {, or be at end
    next_char == ' ' || next_char == '[' || next_char == '{' || next_char == '\t' || next_char == '\r' || next_char == '\n'
}

// Find position of SECOND environment token in a line (first one is assumed at pos 0)
fn find_second_env_token(line: &str) -> Option<usize> {
    // Skip the first token
    let start = if line.starts_with("\\begin{") {
        // Skip \begin{envname}
        skip_env_cmd(line, "\\begin{")
    } else if line.starts_with("\\end{") {
        skip_env_cmd(line, "\\end{")
    } else if is_item_at(line) {
        5 // skip "\item"
    } else {
        0
    };

    // Now search for the next token from 'start'
    let rest = &line[start..];
    if let Some(pos) = find_env_token(rest) {
        Some(start + pos)
    } else {
        None
    }
}

fn skip_env_cmd(line: &str, prefix: &str) -> usize {
    // After \begin{ or \end{, find the closing }
    let start = prefix.len();
    if start >= line.len() {
        return start;
    }
    let bytes = line.as_bytes();
    let mut i = start;
    while i < bytes.len() && bytes[i] != b'}' {
        i += 1;
    }
    if i < bytes.len() {
        i + 1 // skip the }
    } else {
        i
    }
}

// Get environment name from \begin{envname} or \end{envname}
fn get_env_name(line: &str) -> Option<&str> {
    let start = if line.starts_with("\\begin{") {
        7
    } else if line.starts_with("\\end{") {
        5
    } else {
        return None;
    };

    let rest = &line[start..];
    let end = rest.find('}')?;
    Some(&rest[..end])
}

// Check if a line needs environment splitting
fn needs_env_split(line: &str) -> bool {
    let stripped = line.trim_start();

    // Find first token
    if let Some(first_pos) = find_env_token(stripped) {
        if first_pos > 0 {
            // Token not at start of stripped line -> needs split
            return true;
        }
        // Token is at start, check for second token
        if let Some(_second_pos) = find_second_env_token(stripped) {
            return true;
        }
    }
    false
}

// Split a line at the environment token boundary
// Returns (first_part, second_part)
fn split_env_line(line: &str) -> (String, String) {
    let stripped = line.trim_start();
    let leading_spaces = line.len() - stripped.len();
    let prefix = &line[..leading_spaces]; // preserve original leading whitespace? No, we'll strip it

    if let Some(first_pos) = find_env_token(stripped) {
        if first_pos > 0 {
            // Split before the first token
            let first = &stripped[..first_pos];
            let second = &stripped[first_pos..];
            return (first.to_string(), second.to_string());
        }
        // First token is at start, find second
        if let Some(second_pos) = find_second_env_token(stripped) {
            let first = &stripped[..second_pos];
            let second = &stripped[second_pos..];
            return (first.to_string(), second.to_string());
        }
    }

    // No split needed
    (line.to_string(), String::new())
}

// ===== INDENT STATE =====

struct IndentState {
    actual: i32,
    file_type: FileType,
    lists: Vec<String>,
    no_indent_envs: Vec<String>,
    verbatims: Vec<String>,
    in_verbatim: bool,
    verbatim_env: String,
}

impl IndentState {
    fn new(file_type: FileType, lists: Vec<String>, no_indent_envs: Vec<String>, verbatims: Vec<String>) -> Self {
        IndentState {
            actual: 0,
            file_type,
            lists,
            no_indent_envs,
            verbatims,
            in_verbatim: false,
            verbatim_env: String::new(),
        }
    }

    fn env_delta(&self, env_name: &str) -> i32 {
        if self.no_indent_envs.iter().any(|e| e == env_name) {
            0
        } else if self.lists.iter().any(|e| e == env_name) {
            2
        } else {
            1
        }
    }

    fn is_verbatim(&self, env_name: &str) -> bool {
        self.verbatims.iter().any(|e| e == env_name)
    }
}

// Count net braces in a line (stopping at %)
// Returns (min_running_total, final_net)
fn count_braces(line: &str) -> (i32, i32) {
    let mut running = 0i32;
    let mut min_running = 0i32;

    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        match chars[i] {
            '%' => break,
            '{' => {
                running += 1;
            }
            '}' => {
                running -= 1;
                if running < min_running {
                    min_running = running;
                }
            }
            _ => {}
        }
        i += 1;
    }
    (min_running, running)
}

// Count net braces starting from a given byte offset in the line
fn count_braces_from(line: &str, start: usize) -> (i32, i32) {
    if start >= line.len() {
        return (0, 0);
    }
    count_braces(&line[start..])
}

// Process a single line and compute visual indent
// Returns (visual, new_actual)
fn compute_indent(line: &str, state: &mut IndentState) -> i32 {
    let stripped = line.trim_start();

    if stripped.is_empty() {
        // Empty line: visual uses current actual
        return state.actual;
    }

    match state.file_type {
        FileType::Tex => compute_indent_tex(stripped, state),
        FileType::Bib => compute_indent_bib(stripped, state),
    }
}

fn compute_indent_tex(line: &str, state: &mut IndentState) -> i32 {
    // Check for \end{envname}
    if line.starts_with("\\end{") {
        if let Some(env_name) = get_env_name(line) {
            let delta = state.env_delta(env_name);
            state.actual -= delta;
            if state.actual < 0 {
                state.actual = -1; // Will trigger warning
            }
            let visual = state.actual;

            // Count extra braces after \end{envname}
            let skip = 5 + env_name.len() + 1; // \end{ + name + }
            let (min_r, net) = count_braces_from(line, skip);
            let visual_adj = std::cmp::min(0, min_r);
            let visual = visual + visual_adj;
            state.actual += net;

            return visual;
        }
    }

    // Check for \begin{envname}
    if line.starts_with("\\begin{") {
        if let Some(env_name) = get_env_name(line) {
            let visual = state.actual;
            let delta = state.env_delta(env_name);
            state.actual += delta;

            // Count extra braces after \begin{envname}
            let skip = 7 + env_name.len() + 1; // \begin{ + name + }
            let (min_r, net) = count_braces_from(line, skip);
            let visual_adj = std::cmp::min(0, min_r);
            state.actual += net;

            return visual + visual_adj;
        }
    }

    // Check for \item
    if is_item_at(line) {
        let visual = std::cmp::max(0, state.actual - 1);
        // Count braces on the \item line
        let (min_r, net) = count_braces(line);
        let visual_adj = std::cmp::min(0, min_r);
        state.actual += net;
        return visual + visual_adj;
    }

    // Regular line: count net braces
    let (min_r, net) = count_braces(line);
    let visual_adj = std::cmp::min(0, min_r);
    let visual = state.actual + visual_adj;
    state.actual += net;

    visual
}

fn compute_indent_bib(line: &str, state: &mut IndentState) -> i32 {
    // BibTeX: just count braces
    let (min_r, net) = count_braces(line);
    let visual_adj = std::cmp::min(0, min_r);
    let visual = state.actual + visual_adj;
    state.actual += net;
    visual
}

// ===== WRAPPING =====

// Find the wrap point in a line (returns the index to split at, or None)
// The space at that index is the wrap point (first part = line[0..idx], second = line[idx+1..])
fn find_wrap_point(line: &str, wraplen: usize, wrapmin: usize, wrap_chars: &[String]) -> Option<usize> {
    if line.chars().count() <= wraplen {
        return None;
    }

    // Collect character positions 
    let chars: Vec<char> = line.chars().collect();
    let char_count = chars.len();

    // Build byte positions for character indices
    let mut byte_positions: Vec<usize> = Vec::with_capacity(char_count + 1);
    let mut byte_pos = 0;
    for ch in &chars {
        byte_positions.push(byte_pos);
        byte_pos += ch.len_utf8();
    }
    byte_positions.push(byte_pos);

    // Check if char at position i is a wrap point (space or wrap_char)
    // Returns the character index AFTER which we can wrap (space-like char is consumed)

    // Strategy: find last wrap point with char_pos < wrapmin
    // If not found, find first wrap point with char_pos in [wrapmin, wraplen]
    // The "wrap point" position is the char position of the space/wrap-char
    // For space: split BEFORE the space, the space is consumed
    // For wrap_chars: split AFTER the wrap_char

    let mut last_below_wrapmin: Option<usize> = None; // byte index of the space char
    let mut first_in_range: Option<usize> = None;

    for i in 0..char_count {
        let ch = chars[i];
        let is_space = ch == ' ';

        // Check wrap chars
        let ch_str: String = ch.to_string();
        let is_wrap_char = wrap_chars.iter().any(|wc| *wc == ch_str);

        if is_space || is_wrap_char {
            // Position in terms of characters (0-indexed)
            // For space: character i is the space, first part = chars[0..i]
            //   -> first_part_len = i (number of chars before space)
            // For wrap_char: we wrap AFTER this char
            //   -> first_part_len = i + 1

            let first_part_len = if is_space { i } else { i + 1 };

            if first_part_len < wrapmin {
                // This is potentially a "below wrapmin" wrap point
                last_below_wrapmin = Some(i);
            } else if first_part_len >= wrapmin && first_part_len <= wraplen {
                // This is in the [wrapmin, wraplen] range
                if first_in_range.is_none() {
                    first_in_range = Some(i);
                }
            }
        }
    }

    // Return the wrap point character index
    if let Some(idx) = last_below_wrapmin {
        Some(byte_positions[idx])
    } else if let Some(idx) = first_in_range {
        Some(byte_positions[idx])
    } else {
        None
    }
}

// Perform wrapping on a line
// Returns vector of lines (may be multiple if line is very long)
fn wrap_line(line: &str, indent_prefix: &str, visual: i32, actual: i32, tabsize: usize, usetabs: bool, 
             wraplen: usize, wrapmin: usize, wrap_chars: &[String]) -> Vec<(String, i32)> {
    // line here is the FULL indented line
    if line.chars().count() <= wraplen {
        return vec![(line.to_string(), visual)];
    }

    if let Some(split_byte) = find_wrap_point(line, wraplen, wrapmin, wrap_chars) {
        let char_at_split = line[split_byte..].chars().next().unwrap_or(' ');
        let is_space_split = char_at_split == ' ';

        let (first, second) = if is_space_split {
            // Split at space: first part doesn't include space
            let first = line[..split_byte].to_string();
            let second_start = split_byte + 1; // skip the space
            if second_start >= line.len() {
                return vec![(first, visual)];
            }
            let second_content = &line[second_start..];
            // Second part gets indent of actual (visual = actual)
            let new_indent = make_indent(actual, tabsize, usetabs);
            let second = format!("{}{}", new_indent, second_content.trim_start());
            (first, second)
        } else {
            // Wrap char: split AFTER the char
            let first_end = split_byte + char_at_split.len_utf8();
            let first = line[..first_end].to_string();
            let second_content = &line[first_end..];
            let new_indent = make_indent(actual, tabsize, usetabs);
            let second = format!("{}{}", new_indent, second_content.trim_start());
            (first, second)
        };

        let first_trimmed = first.trim_end().to_string();

        // Recursively wrap the second part
        let mut result = vec![(first_trimmed, visual)];
        let mut continuation = wrap_line(&second, indent_prefix, actual, actual, tabsize, usetabs, wraplen, wrapmin, wrap_chars);
        result.append(&mut continuation);
        result
    } else {
        // Cannot wrap
        vec![(line.to_string(), visual)]
    }
}

fn make_indent(visual: i32, tabsize: usize, usetabs: bool) -> String {
    if visual <= 0 {
        return String::new();
    }
    let n = (visual as usize) * tabsize;
    if usetabs {
        "\t".repeat(n)
    } else {
        " ".repeat(n)
    }
}

// ===== MAIN FORMATTING FUNCTION =====

struct FormatResult {
    content: String,
    changed: bool,
    has_warnings: bool,
}

fn format_content(
    content: &str,
    filename: &str,
    cfg: &Config,
    file_type: FileType,
) -> FormatResult {
    let verbosity = &cfg.verbosity;

    log_info(verbosity, filename, "Formatting started.");

    // Split into lines, preserving line endings info
    let lines: Vec<&str> = content.lines().collect();

    let mut state = IndentState::new(
        file_type.clone(),
        cfg.lists.clone(),
        cfg.no_indent_envs.clone(),
        cfg.verbatims.clone(),
    );

    let mut output_lines: Vec<String> = Vec::new();
    let mut output_line_num = 1usize;
    let mut last_nonindented_line: Option<usize> = None;
    let mut first_negative_line: Option<usize> = None;
    let mut has_warnings = false;

    let mut line_queue: VecDeque<(String, usize)> = VecDeque::new(); // (content, source_line)

    for (line_idx, &line) in lines.iter().enumerate() {
        line_queue.push_back((line.trim_end().to_string(), line_idx + 1));
    }

    while let Some((line, source_line)) = line_queue.pop_front() {
        // Handle verbatim environments
        if state.in_verbatim {
            // Check if this line ends the verbatim env
            let stripped = line.trim_start();
            let end_pattern = format!("\\end{{{}}}", state.verbatim_env);
            if stripped.starts_with(&end_pattern) {
                state.in_verbatim = false;
                state.verbatim_env = String::new();
            }
            // Output verbatim line as-is (no indentation, no wrapping)
            output_lines.push(line.trim_end().to_string());
            output_line_num += 1;
            continue;
        }

        // Check for verbatim begin
        let stripped_for_verbatim = line.trim_start();
        if stripped_for_verbatim.starts_with("\\begin{") {
            if let Some(env_name) = get_env_name(stripped_for_verbatim) {
                if state.is_verbatim(env_name) {
                    // Enter verbatim mode
                    state.in_verbatim = true;
                    state.verbatim_env = env_name.to_string();
                    // Output the \begin{verbatim} line as-is
                    output_lines.push(line.trim_end().to_string());
                    output_line_num += 1;
                    continue;
                }
            }
        }

        // Check if line needs environment splitting
        let stripped = line.trim_start();
        if needs_env_split(stripped) {
            let (first, second) = split_env_line(stripped);
            log_trace(verbosity, filename, &format!(
                "Line {} ({}). Placing environment on new line. {}",
                output_line_num, source_line, stripped
            ));
            // Push first part back as current, second part to front of queue
            line_queue.push_front((second, source_line));
            line_queue.push_front((first, source_line));
            continue;
        }

        // Process this line
        let stripped = line.trim_start();

        // Compute visual indent
        let visual = compute_indent(stripped, &mut state);
        let actual = state.actual;

        // Build indented line
        let indent_str = make_indent(visual, cfg.tabsize, cfg.usetabs);
        let full_line = if stripped.is_empty() {
            String::new() // Empty lines get no indent
        } else {
            format!("{}{}", indent_str, stripped)
        };

        log_trace(verbosity, filename, &format!(
            "Line {} ({}). Indent: actual = {}, visual = {}: {}",
            output_line_num, source_line, actual, visual, stripped
        ));

        // Warn on negative indent
        if actual < 0 {
            log_warn(verbosity, filename, &format!(
                "Line {} ({}). Indent is negative. {}",
                output_line_num, source_line, stripped
            ));
            has_warnings = true;
            if first_negative_line.is_none() {
                first_negative_line = Some(source_line);
            }
        }

        // Track last non-indented line for the "does not return to zero" warning
        if visual == 0 && !stripped.is_empty() {
            last_nonindented_line = Some(source_line);
        }

        // Apply wrapping if needed
        if cfg.wrap && !full_line.is_empty() && full_line.chars().count() > cfg.wraplen {
            log_trace(verbosity, filename, &format!(
                "Line {} ({}). Wrapping long line. {}",
                output_line_num, source_line, stripped
            ));

            let wrapped = wrap_line(&full_line, &indent_str, visual, actual, 
                                    cfg.tabsize, cfg.usetabs, 
                                    cfg.wraplen, cfg.wrapmin, &cfg.wrap_chars);

            // Check if wrapping actually helped
            let first_wrapped = &wrapped[0].0;
            if wrapped.len() == 1 && first_wrapped.chars().count() > cfg.wraplen {
                log_warn(verbosity, filename, &format!(
                    "Line {} ({}). Line cannot be wrapped. {}",
                    output_line_num, source_line, stripped
                ));
                has_warnings = true;
            }

            for (i, (wline, wvisual)) in wrapped.iter().enumerate() {
                let wline_trimmed = wline.trim_end().to_string();
                if i == 0 {
                    log_trace(verbosity, filename, &format!(
                        "Line {} ({}). Indent: actual = {}, visual = {}: {}",
                        output_line_num, source_line, actual, visual,
                        wline_trimmed.trim_start()
                    ));
                    output_lines.push(wline_trimmed);
                    output_line_num += 1;
                } else {
                    log_trace(verbosity, filename, &format!(
                        "Line {} ({}). Indent: actual = {}, visual = {}: {}",
                        output_line_num, source_line, actual, *wvisual,
                        wline_trimmed.trim_start()
                    ));
                    output_lines.push(wline_trimmed);
                    output_line_num += 1;
                }
            }
        } else {
            let trimmed = full_line.trim_end().to_string();
            output_lines.push(trimmed);
            output_line_num += 1;
        }
    }

    // Check if indent returns to zero
    if state.actual != 0 {
        if let Some(last_line) = last_nonindented_line {
            log_warn(verbosity, filename, &format!(
                "Indent does not return to zero. Last non-indented line is line {}",
                last_line
            ));
            has_warnings = true;
        }
    }

    if let Some(neg_line) = first_negative_line {
        log_warn(verbosity, filename, &format!(
            "Negative indents. First negatively indented line is line {}",
            neg_line
        ));
        has_warnings = true;
    }

    log_info(verbosity, filename, "Formatting complete.");

    let mut result = output_lines.join("\n");
    // Ensure single trailing newline
    if !result.ends_with('\n') {
        result.push('\n');
    }

    let changed = result != content;

    FormatResult {
        content: result,
        changed,
        has_warnings,
    }
}

// ===== FILE PROCESSING =====

fn process_file(path: &str, cfg: &Config) -> i32 {
    // Check file type
    let file_type = match get_file_type(path) {
        Some(ft) => ft,
        None => {
            log_error(&cfg.verbosity, path, "File type invalid.");
            return 1;
        }
    };

    // Read file
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => {
            log_error(&cfg.verbosity, path, "Could not open file.");
            return 1;
        }
    };

    let result = format_content(&content, path, cfg, file_type);

    if cfg.check {
        if result.changed {
            log_error(&cfg.verbosity, path, "Incorrect formatting.");
            return 1;
        }
    } else if cfg.print {
        print!("{}", result.content);
    } else {
        // Write back to file
        if result.changed {
            if let Err(_) = fs::write(path, &result.content) {
                log_error(&cfg.verbosity, path, "Could not write file.");
                return 1;
            }
            if cfg.fail_on_change {
                return 1;
            }
        }
    }

    0
}

fn process_stdin(cfg: &Config) -> i32 {
    let mut content = String::new();
    match io::stdin().read_to_string(&mut content) {
        Ok(n) => {
            log_trace(&cfg.verbosity, "<stdin>", &format!("Read {} bytes.", n));
        }
        Err(_) => {
            log_error(&cfg.verbosity, "<stdin>", "Could not read stdin.");
            return 1;
        }
    }

    // For stdin, use tex file type by default
    let result = format_content(&content, "<stdin>", cfg, FileType::Tex);
    print!("{}", result.content);
    0
}

fn collect_files_recursive(dir: &str, files: &mut Vec<String>) {
    let path = Path::new(dir);
    if path.is_file() {
        let s = path.to_string_lossy().to_string();
        if get_file_type(&s).is_some() {
            files.push(s);
        }
        return;
    }

    if let Ok(entries) = fs::read_dir(path) {
        let mut sorted_entries: Vec<_> = entries.filter_map(|e| e.ok()).collect();
        sorted_entries.sort_by_key(|e| e.path());

        for entry in sorted_entries {
            let entry_path = entry.path();
            let entry_str = entry_path.to_string_lossy().to_string();
            if entry_path.is_dir() {
                collect_files_recursive(&entry_str, files);
            } else if entry_path.is_file() {
                if get_file_type(&entry_str).is_some() {
                    files.push(entry_str);
                }
            }
        }
    }
}

