        Verbosity::Trace => "trace",
    });
    // Print lists
    let indent = "                           ";
    let first_list = cfg.lists.first().map(|s| s.as_str()).unwrap_or("");
    println!("  lists:                   {}", first_list);
    for item in cfg.lists.iter().skip(1) {
