// ===== MAIN =====

fn main() {
    let cfg = match parse_args() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    let mut exit_code = 0;

    if cfg.stdin {
        exit_code = process_stdin(&cfg);
    } else if cfg.recursive {
        let mut all_files: Vec<String> = Vec::new();

        if cfg.files.is_empty() {
            collect_files_recursive(".", &mut all_files);
        } else {
            for f in &cfg.files {
                collect_files_recursive(f, &mut all_files);
            }
        }

        for file in &all_files {
            let r = process_file(file, &cfg);
            if r != 0 {
                exit_code = r;
            }
        }
    } else if cfg.files.is_empty() {
        log_error(&cfg.verbosity, "", "No files specified. Provide filenames, or pass --recursive or --stdin.");
        exit_code = 1;
    } else {
        for file in &cfg.files.clone() {
            let r = process_file(file, &cfg);
            if r != 0 {
                exit_code = r;
            }
        }
    }

    std::process::exit(exit_code);
}
