// ===== TOML PARSER (simple) =====

fn parse_toml_config(content: &str, cfg: &mut Config) -> Result<(), String> {
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(eq_pos) = line.find('=') {
            let key = line[..eq_pos].trim();
            let val = line[eq_pos+1..].trim();
            match key {
                "check" => cfg.check = val == "true",
                "print" => cfg.print = val == "true",
                "fail-on-change" => cfg.fail_on_change = val == "true",
                "wrap" => cfg.wrap = val == "true",
                "wraplen" => {
                    if let Ok(n) = val.parse::<usize>() {
                        cfg.wraplen = n;
                        cfg.wrapmin = if n >= 10 { n - 10 } else { 0 };
                    }
                }
                "wrapmin" => {
                    if let Ok(n) = val.parse::<usize>() {
                        cfg.wrapmin = n;
                    }
                }
                "tabsize" => {
                    if let Ok(n) = val.parse::<usize>() {
                        cfg.tabsize = n;
                    }
                }
                "tabchar" => {
                    cfg.usetabs = val.trim_matches('"') == "tab";
                }
                "stdin" => cfg.stdin = val == "true",
                "verbosity" => {
                    match val.trim_matches('"') {
                        "error" => cfg.verbosity = Verbosity::Error,
                        "warn" => cfg.verbosity = Verbosity::Warn,
                        "info" => cfg.verbosity = Verbosity::Info,
                        "trace" => cfg.verbosity = Verbosity::Trace,
                        _ => {}
                    }
                }
                "lists" => {
                    // Parse array like ["a", "b"]
                    let items = parse_toml_string_array(val);
                    let default_lists: Vec<String> = vec![
                        "itemize".to_string(),
                        "enumerate".to_string(),
                        "description".to_string(),
                        "inlineroman".to_string(),
                        "inventory".to_string(),
                    ];
                    cfg.lists = items.into_iter().chain(default_lists.into_iter()).collect();
                }
                "verbatims" => {
                    let items = parse_toml_string_array(val);
                    let default_verbatims: Vec<String> = vec![
                        "verbatim".to_string(),
                        "Verbatim".to_string(),
                        "lstlisting".to_string(),
                        "minted".to_string(),
                        "comment".to_string(),
                    ];
                    cfg.verbatims = items.into_iter().chain(default_verbatims.into_iter()).collect();
                }
                "no-indent-envs" => {
                    let items = parse_toml_string_array(val);
                    let default_no_indent: Vec<String> = vec!["document".to_string()];
                    cfg.no_indent_envs = items.into_iter().chain(default_no_indent.into_iter()).collect();
                }
                "wrap-chars" => {
                    cfg.wrap_chars = parse_toml_string_array(val);
                }
                _ => {}
            }
        }
    }
    Ok(())
}

fn parse_toml_string_array(val: &str) -> Vec<String> {
    // Parse ["a", "b", "c"] or multiline arrays
    let mut result = Vec::new();
    let content = val.trim();

    // Handle inline array
    if content.starts_with('[') {
        let inner = content.trim_start_matches('[').trim_end_matches(']');
        for item in inner.split(',') {
            let s = item.trim().trim_matches('"');
            if !s.is_empty() {
                result.push(s.to_string());
            }
        }
    }
    result
}

// ===== ARGUMENT PARSING =====

fn parse_args() -> Result<Config, String> {
    let args: Vec<String> = std::env::args().collect();
    let mut cfg = Config::default();
    // Default wrapmin = wraplen - 10
    cfg.wrapmin = cfg.wraplen - 10;

    let mut i = 1;
    let mut show_help = false;
    let mut show_version = false;
    let mut show_args = false;
    let mut show_man = false;
    let mut completion_shell: Option<String> = None;
    let mut cli_wraplen: Option<usize> = None;
    let mut cli_wrapmin: Option<usize> = None;

    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => { show_help = true; }
            "-V" | "--version" => { show_version = true; }
            "--args" => { show_args = true; }
            "--man" => { show_man = true; }
            "-c" | "--check" => { cfg.check = true; }
            "-p" | "--print" => { cfg.print = true; }
            "-f" | "--fail-on-change" => { cfg.fail_on_change = true; }
            "-n" | "--nowrap" => { cfg.wrap = false; }
            "-s" | "--stdin" => { cfg.stdin = true; }
            "-v" | "--verbose" => { cfg.verbosity = Verbosity::Info; }
            "-q" | "--quiet" => { cfg.verbosity = Verbosity::Error; }
            "--trace" => { cfg.verbosity = Verbosity::Trace; }
            "--usetabs" => { cfg.usetabs = true; }
            "--noconfig" => { cfg.noconfig = true; }
            "-r" | "--recursive" => { cfg.recursive = true; }
            "-l" | "--wraplen" => {
                i += 1;
                if i < args.len() {
                    if let Ok(n) = args[i].parse::<usize>() {
                        cli_wraplen = Some(n);
                    }
                }
            }
            "-t" | "--tabsize" => {
                i += 1;
                if i < args.len() {
                    if let Ok(n) = args[i].parse::<usize>() {
                        cfg.tabsize = n;
                    }
                }
            }
            "--config" => {
                i += 1;
                if i < args.len() {
                    cfg.config_path = Some(args[i].clone());
                }
            }
            "--completion" => {
                i += 1;
                if i < args.len() {
                    completion_shell = Some(args[i].clone());
                }
            }
            _ => {
                // Check for --flag=value format
                if args[i].starts_with("--wraplen=") {
                    if let Ok(n) = args[i]["--wraplen=".len()..].parse::<usize>() {
                        cli_wraplen = Some(n);
                    }
                } else if args[i].starts_with("--tabsize=") {
                    if let Ok(n) = args[i]["--tabsize=".len()..].parse::<usize>() {
                        cfg.tabsize = n;
                    }
                } else if args[i].starts_with("--config=") {
                    cfg.config_path = Some(args[i]["--config=".len()..].to_string());
                } else if args[i].starts_with("--completion=") {
                    completion_shell = Some(args[i]["--completion=".len()..].to_string());
                } else if args[i].starts_with('-') {
                    // Unknown flag, ignore
                } else {
                    // File argument
                    cfg.files.push(args[i].clone());
                }
            }
        }
        i += 1;
    }

    // Handle special commands that exit immediately
    if show_version {
        println!("tex-fmt 0.5.6");
        std::process::exit(0);
    }
    if show_help {
        print_help();
        std::process::exit(0);
    }
    if show_man {
        print_man();
        std::process::exit(0);
    }
    if let Some(shell) = completion_shell {
        print_completion(&shell);
        std::process::exit(0);
    }

    // Load config file BEFORE processing cli overrides
    if !cfg.noconfig {
        if let Some(ref path) = cfg.config_path.clone() {
            // Named config file
            match fs::read_to_string(path) {
                Ok(content) => {
                    let mut file_cfg = Config::default();
                    file_cfg.wrapmin = file_cfg.wraplen - 10;
                    let _ = parse_toml_config(&content, &mut file_cfg);
                    // Apply file config to cfg (file overrides defaults but CLI overrides file)
                    apply_file_config(&mut cfg, &file_cfg);
                }
                Err(_) => {
                    eprintln!("ERROR: tex-fmt : Could not open config file {}. ", path);
                }
            }
        } else {
            // Search for tex-fmt.toml
            if let Some(config_content) = find_config_file() {
                let mut file_cfg = Config::default();
                file_cfg.wrapmin = file_cfg.wraplen - 10;
                let _ = parse_toml_config(&config_content, &mut file_cfg);
                apply_file_config(&mut cfg, &file_cfg);
            }
        }
    }

    // Apply CLI wraplen overrides
    if let Some(wl) = cli_wraplen {
        cfg.wraplen = wl;
        if cli_wrapmin.is_none() {
            cfg.wrapmin = if wl >= 10 { wl - 10 } else { 0 };
        }
    }
    if let Some(wm) = cli_wrapmin {
        cfg.wrapmin = wm;
    }

    // When check is set, print also gets set (check is print without writing)
    // Actually --check implies we don't modify files, same as --print
    // When --print is set, fail-on-change is also implicitly true? Let me check.
    // From --args test: --print implies fail-on-change=true
    // This seems to be just for the args display, not actual behavior

    if show_args {
        print_args(&cfg);
        std::process::exit(0);
    }

    Ok(cfg)
}

fn apply_file_config(cfg: &mut Config, file_cfg: &Config) {
    // Apply non-default values from file_cfg to cfg
    // (We only apply if cfg still has default values)
    // Actually for a proper implementation, we'd need to track what was set by CLI vs file
    // For simplicity, we'll just use the file config for things not explicitly set on CLI
    // This is tricky without tracking explicitly - let me just apply file config completely
    // and then CLI args will override (since CLI args are parsed after in our flow)

    // The simplest approach: apply file config to cfg
    // This function is called AFTER initial cfg setup from CLI args
    // We want file config to override DEFAULTS but NOT CLI args
    // Since we can't easily distinguish, let's just copy the lists/verbatims/etc.

    // For now, just apply the extra lists/verbatims/etc from file
    cfg.lists = file_cfg.lists.clone();
    cfg.verbatims = file_cfg.verbatims.clone();
    cfg.no_indent_envs = file_cfg.no_indent_envs.clone();
    cfg.wrap_chars = file_cfg.wrap_chars.clone();
}

fn find_config_file() -> Option<String> {
    // Look for tex-fmt.toml in:
    // 1. Current directory
    // 2. Root of git repository
    // 3. User config dir

    // Current directory
    if let Ok(content) = fs::read_to_string("tex-fmt.toml") {
        return Some(content);
    }

    // Git root
    if let Ok(output) = std::process::Command::new("git")
        .args(["rev-parse", "--show-toplevel"])
        .output() 
    {
        if output.status.success() {
            let git_root = String::from_utf8_lossy(&output.stdout).trim().to_string();
            let path = format!("{}/tex-fmt.toml", git_root);
            if let Ok(content) = fs::read_to_string(&path) {
                return Some(content);
            }
        }
    }

    // User config dir
    if let Some(home) = std::env::var_os("HOME") {
        let config_path = PathBuf::from(home)
            .join(".config")
            .join("tex-fmt")
            .join("tex-fmt.toml");
        if let Ok(content) = fs::read_to_string(&config_path) {
            return Some(content);
        }
    }

    None
}

