            verbatims: default_verbatims(),
            no_indent_envs: default_no_indent_envs(),
            wrap_chars: vec![],
            recursive: false,
            files: vec![],
        }
    }
}

fn default_lists() -> Vec<String> {
    vec![
        "itemize".to_string(),
        "enumerate".to_string(),
        "description".to_string(),
        "inlineroman".to_string(),
        "inventory".to_string(),
    ]
}

fn default_verbatims() -> Vec<String> {
    vec![
        "verbatim".to_string(),
        "Verbatim".to_string(),
        "lstlisting".to_string(),
        "minted".to_string(),
        "comment".to_string(),
    ]
}

fn default_no_indent_envs() -> Vec<String> {
    vec!["document".to_string()]
}

// ===== TOML PARSER (simple, for config files) =====

fn parse_toml_config(content: &str, cfg: &mut Config) {
    // We need to handle multi-line arrays properly
    // Collect all lines and handle continuations
    let mut full_content = String::new();
    let mut in_array = false;
    let mut current_key = String::new();
    let mut array_content = String::new();

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        if in_array {
            array_content.push_str(trimmed);
            if trimmed.contains(']') {
                in_array = false;
                // Process the completed array
                process_toml_kv(&current_key, &array_content, cfg);
                current_key.clear();
                array_content.clear();
            }
            continue;
        }

        if let Some(eq_pos) = trimmed.find('=') {
            let key = trimmed[..eq_pos].trim().to_string();
            let val = trimmed[eq_pos+1..].trim();

            // Check if it's a multi-line array
            if val.starts_with('[') && !val.contains(']') {
                in_array = true;
                current_key = key;
                array_content = val.to_string();
            } else {
                process_toml_kv(&key, val, cfg);
            }
        }
    }
}

fn process_toml_kv(key: &str, val: &str, cfg: &mut Config) {
    match key {
        "check" => cfg.check = val == "true",
        "print" => cfg.print = val == "true",
        "fail-on-change" => cfg.fail_on_change = val == "true",
        "wrap" => cfg.wrap = val == "true",
        "wraplen" => {
            if let Ok(n) = val.parse::<usize>() {
                cfg.wraplen = n;
                cfg.wrapmin = if n >= 10 { n - 10 } else { 0 };
            }
        }
        "wrapmin" => {
            if let Ok(n) = val.parse::<usize>() {
                cfg.wrapmin = n;
            }
        }
        "tabsize" => {
            if let Ok(n) = val.parse::<usize>() {
                cfg.tabsize = n;
            }
        }
        "tabchar" => {
            cfg.usetabs = val.trim_matches('"') == "tab";
        }
        "stdin" => cfg.stdin = val == "true",
        "verbosity" => {
            match val.trim_matches('"') {
                "error" => cfg.verbosity = Verbosity::Error,
                "warn" => cfg.verbosity = Verbosity::Warn,
                "info" => cfg.verbosity = Verbosity::Info,
                "trace" => cfg.verbosity = Verbosity::Trace,
                _ => {}
            }
        }
        "lists" => {
            let items = parse_toml_string_array(val);
            cfg.lists = items.into_iter().chain(default_lists().into_iter()).collect();
        }
        "verbatims" => {
            let items = parse_toml_string_array(val);
            cfg.verbatims = items.into_iter().chain(default_verbatims().into_iter()).collect();
        }
        "no-indent-envs" => {
            let items = parse_toml_string_array(val);
            cfg.no_indent_envs = items.into_iter().chain(default_no_indent_envs().into_iter()).collect();
        }
        "wrap-chars" => {
            cfg.wrap_chars = parse_toml_string_array(val);
        }
        _ => {}
    }
}

fn parse_toml_string_array(val: &str) -> Vec<String> {
    let mut result = Vec::new();
    // Handle arrays like ["a", "b", "c"]
    let s = val.trim();

    // Find content between [ and ]
    let start = s.find('[').unwrap_or(0) + 1;
    let end = s.rfind(']').unwrap_or(s.len());

    if start >= end {
        return result;
    }

    let inner = &s[start..end];

    // Parse comma-separated quoted strings
    let mut current = String::new();
    let mut in_quotes = false;
    let mut quote_char = '"';

    for ch in inner.chars() {
        if in_quotes {
            if ch == quote_char {
                result.push(current.clone());
                current.clear();
                in_quotes = false;
            } else {
                current.push(ch);
            }
        } else {
            if ch == '"' || ch == '\'' {
                in_quotes = true;
                quote_char = ch;
            }
            // Skip commas, spaces outside quotes
        }
    }

    result
}

// ===== ARGUMENT PARSING =====

fn parse_args() -> Config {
    let args: Vec<String> = std::env::args().collect();

    // First pass: collect CLI overrides
    let mut cli = Config::default_config();
    let mut show_help = false;
    let mut show_version = false;
    let mut show_args = false;
    let mut show_man = false;
    let mut completion_shell: Option<String> = None;
    let mut cli_wraplen_set = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => show_help = true,
            "-V" | "--version" => show_version = true,
            "--args" => show_args = true,
            "--man" => show_man = true,
            "-c" | "--check" => cli.check = true,
            "-p" | "--print" => cli.print = true,
            "-f" | "--fail-on-change" => cli.fail_on_change = true,
            "-n" | "--nowrap" => cli.wrap = false,
            "-s" | "--stdin" => cli.stdin = true,
            "-v" | "--verbose" => cli.verbosity = Verbosity::Info,
            "-q" | "--quiet" => cli.verbosity = Verbosity::Error,
            "--trace" => cli.verbosity = Verbosity::Trace,
            "--usetabs" => cli.usetabs = true,
            "--noconfig" => cli.noconfig = true,
            "-r" | "--recursive" => cli.recursive = true,
            "-l" | "--wraplen" => {
                i += 1;
                if i < args.len() {
                    if let Ok(n) = args[i].parse::<usize>() {
                        cli.wraplen = n;
                        cli.wrapmin = if n >= 10 { n - 10 } else { 0 };
                        cli_wraplen_set = true;
                    }
                }
            }
            "-t" | "--tabsize" => {
                i += 1;
                if i < args.len() {
                    if let Ok(n) = args[i].parse::<usize>() {
                        cli.tabsize = n;
                    }
                }
            }
            "--config" => {
                i += 1;
                if i < args.len() {
                    cli.config_path = Some(args[i].clone());
                }
            }
            "--completion" => {
                i += 1;
                if i < args.len() {
                    completion_shell = Some(args[i].clone());
                }
            }
            s if s.starts_with("--wraplen=") => {
                if let Ok(n) = s["--wraplen=".len()..].parse::<usize>() {
                    cli.wraplen = n;
                    cli.wrapmin = if n >= 10 { n - 10 } else { 0 };
                    cli_wraplen_set = true;
                }
            }
            s if s.starts_with("--tabsize=") => {
                if let Ok(n) = s["--tabsize=".len()..].parse::<usize>() {
                    cli.tabsize = n;
                }
            }
            s if s.starts_with("--config=") => {
                cli.config_path = Some(s["--config=".len()..].to_string());
            }
            s if s.starts_with("--completion=") => {
                completion_shell = Some(s["--completion=".len()..].to_string());
            }
            s if !s.starts_with('-') => {
                cli.files.push(s.to_string());
            }
            _ => {} // Ignore unknown flags
        }
        i += 1;
    }

    // Handle special display commands
    if show_version {
        println!("tex-fmt 0.5.6");
        std::process::exit(0);
    }
    if show_help {
        print_help();
        std::process::exit(0);
    }
    if show_man {
        print_man();
        std::process::exit(0);
    }
    if let Some(shell) = completion_shell {
        print_completion(&shell);
        std::process::exit(0);
    }

    // Load config file and merge with CLI
    let mut cfg = Config::default_config();

    if !cli.noconfig {
        let config_content = if let Some(ref path) = cli.config_path {
            match fs::read_to_string(path) {
                Ok(c) => Some(c),
                Err(_) => None,
            }
        } else {
            find_config_file()
        };

        if let Some(content) = config_content {
            parse_toml_config(&content, &mut cfg);
            // After config, cfg.wrapmin was set relative to cfg.wraplen
            // But if CLI sets wraplen, it should override
        }
    }

    // Apply CLI overrides on top of config
    // (CLI always wins)
    if cli.check { cfg.check = true; }
    if cli.print { cfg.print = true; }
    if cli.fail_on_change { cfg.fail_on_change = true; }
    if !cli.wrap { cfg.wrap = false; } // nowrap CLI
    if cli_wraplen_set { 
        cfg.wraplen = cli.wraplen;
        cfg.wrapmin = cli.wrapmin;
    }
    if cli.tabsize != 2 { cfg.tabsize = cli.tabsize; }
    if cli.usetabs { cfg.usetabs = true; }
    if cli.stdin { cfg.stdin = true; }
    if cli.noconfig { cfg.noconfig = true; }
    if cli.recursive { cfg.recursive = true; }
    cfg.config_path = cli.config_path.clone();
    cfg.files = cli.files.clone();

    // Verbosity: CLI wins
    match (&cli.verbosity, &Config::default_config().verbosity) {
        (Verbosity::Warn, _) => {} // CLI didn't change verbosity explicitly
        (v, _) => cfg.verbosity = v.clone(),
    }

    // Ugh, detecting "was CLI verbosity set" is tricky without more tracking
    // Let me just use a simpler approach: track if verbosity CLI args were found
    // and re-parse

    // Actually the simplest fix: just re-parse CLI verbosity
    let mut verbosity_set = false;
    let args: Vec<String> = std::env::args().collect();
    for arg in &args {
        match arg.as_str() {
            "-v" | "--verbose" => { cfg.verbosity = Verbosity::Info; verbosity_set = true; }
            "-q" | "--quiet" => { cfg.verbosity = Verbosity::Error; verbosity_set = true; }
            "--trace" => { cfg.verbosity = Verbosity::Trace; verbosity_set = true; }
            _ => {}
        }
    }

    if show_args {
        print_args(&cfg);
        std::process::exit(0);
    }

    cfg
}

fn find_config_file() -> Option<String> {
    // 1. Current directory
    if let Ok(content) = fs::read_to_string("tex-fmt.toml") {
        return Some(content);
    }

    // 2. Git root
    if let Ok(output) = std::process::Command::new("git")
        .args(["rev-parse", "--show-toplevel"])
        .output()
    {
        if output.status.success() {
            let git_root = String::from_utf8_lossy(&output.stdout).trim().to_string();
            let path = format!("{}/tex-fmt.toml", git_root);
            if let Ok(content) = fs::read_to_string(&path) {
                return Some(content);
            }
        }
    }

    // 3. User config dir
    if let Some(home) = std::env::var_os("HOME") {
        let config_path = PathBuf::from(home)
            .join(".config")
            .join("tex-fmt")
            .join("tex-fmt.toml");
        if let Ok(content) = fs::read_to_string(&config_path) {
            return Some(content);
        }
    }

    None
}

// ===== LOGGING =====

fn log_error(verbosity: &Verbosity, filename: &str, msg: &str) {
    // Errors always shown
    eprintln!("ERROR: tex-fmt {}: {} ", filename, msg);
}

fn log_warn(verbosity: &Verbosity, filename: &str, msg: &str) {
    if matches!(verbosity, Verbosity::Warn | Verbosity::Info | Verbosity::Trace) {
        eprintln!("WARN: tex-fmt {}: {} ", filename, msg);
    }
}

fn log_info(verbosity: &Verbosity, filename: &str, msg: &str) {
    if matches!(verbosity, Verbosity::Info | Verbosity::Trace) {
        eprintln!("INFO: tex-fmt {}: {} ", filename, msg);
    }
}

fn log_trace(verbosity: &Verbosity, filename: &str, msg: &str) {
    if *verbosity == Verbosity::Trace {
        eprintln!("TRACE: tex-fmt {}: {}", filename, msg);
    }
}

// ===== FILE TYPE =====

#[derive(Debug, Clone, PartialEq)]
enum FileType {
    Tex,
    Bib,
}

fn get_file_type(filename: &str) -> Option<FileType> {
    // Strip path, just use extension
    let name = Path::new(filename)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(filename);

    let lower = name.to_lowercase();
    if lower.ends_with(".tex") || lower.ends_with(".sty") || lower.ends_with(".cls") {
        Some(FileType::Tex)
    } else if lower.ends_with(".bib") {
        Some(FileType::Bib)
    } else {
        None
    }
}

// ===== ENVIRONMENT DETECTION =====

// Returns position (byte index) of the start of a \begin{}, \end{}, or \item token
// Returns None if found only in comments
fn find_env_token_in_line(line: &str) -> Option<usize> {
    let bytes = line.as_bytes();
    let len = bytes.len();
    let mut i = 0;

    while i < len {
        if bytes[i] == b'%' {
            return None; // Rest is comment
        }
        if bytes[i] == b'\\' && i + 1 < len {
            let rest = &line[i..];
            if rest.starts_with("\\begin{") || rest.starts_with("\\end{") || is_item_token(rest) {
                return Some(i);
            }
        }
        // Advance by one character (handling multi-byte)
        let ch_len = if bytes[i] < 0x80 { 1 } else {
            line[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1)
        };
        i += ch_len;
    }
    None
}

fn is_item_token(s: &str) -> bool {
    if !s.starts_with("\\item") {
        return false;
    }
    let after = &s[5..]; // after "\item"
    if after.is_empty() {
        return true;
    }
    matches!(after.chars().next(), Some(' ') | Some('[') | Some('{') | Some('\t'))
}

// Find the SECOND env token in a line, starting from after the first one at position 0
fn find_second_env_token(line: &str) -> Option<usize> {
    // Skip first token at position 0
    let skip = if line.starts_with("\\begin{") {
        skip_past_env_name(line, 7) // len("\\begin{") = 7
    } else if line.starts_with("\\end{") {
        skip_past_env_name(line, 5) // len("\\end{") = 5
    } else if is_item_token(line) {
        5 // len("\\item") = 5
    } else {
        0
    };

    if skip >= line.len() {
        return None;
    }

    // Search for next token from skip position
    find_env_token_in_line_from(line, skip)
}

fn find_env_token_in_line_from(line: &str, start: usize) -> Option<usize> {
    if start >= line.len() {
        return None;
    }
    let result = find_env_token_in_line(&line[start..]);
    result.map(|pos| start + pos)
}

fn skip_past_env_name(line: &str, cmd_len: usize) -> usize {
    // line starts with \begin{ or \end{ (cmd_len chars)
    // Find the closing }
    let start = cmd_len;
    if start >= line.len() {
        return start;
    }
    let bytes = line.as_bytes();
    let mut i = start;
    while i < bytes.len() && bytes[i] != b'}' {
        i += 1;
    }
    if i < bytes.len() {
        i + 1 // skip the }
    } else {
        i
    }
}

// Get environment name from \begin{envname} or \end{envname}
fn get_env_name(line: &str) -> Option<&str> {
    let start = if line.starts_with("\\begin{") {
        7
    } else if line.starts_with("\\end{") {
        5
    } else {
        return None;
    };

    let rest = &line[start..];
    let end = rest.find('}')?;
    Some(&rest[..end])
}

// Check if a (stripped) line needs env splitting
fn needs_env_split(line: &str) -> bool {
    if let Some(first_pos) = find_env_token_in_line(line) {
        if first_pos > 0 {
            // Token not at start -> needs split
            return true;
        }
        // Token at start -> check for second token
        if find_second_env_token(line).is_some() {
            return true;
        }
    }
    false
}

// Split at the appropriate position
// Returns (first_part, second_part) where second_part starts with the env token
fn split_env_line(line: &str) -> (String, String) {
    if let Some(first_pos) = find_env_token_in_line(line) {
        if first_pos > 0 {
            // Split before first token
            return (line[..first_pos].to_string(), line[first_pos..].to_string());
        }
        // First token at start, find second
        if let Some(second_pos) = find_second_env_token(line) {
            return (line[..second_pos].to_string(), line[second_pos..].to_string());
        }
    }
    (line.to_string(), String::new())
}

// ===== BRACE COUNTING =====

// Count net braces in a line (stopping at %)
// Returns (min_running, final_net)
// Both exclude braces in \begin{} and \end{} env name
fn count_braces_tex(line: &str) -> (i32, i32) {
    let mut running = 0i32;
    let mut min_running = 0i32;
    let bytes = line.as_bytes();
    let len = bytes.len();
    let mut i = 0;

    while i < len {
        match bytes[i] {
            b'%' => break,
            b'\\' => {
                // Check if this is \begin or \end - skip their braces
                let rest = &line[i..];
                if rest.starts_with("\\begin{") || rest.starts_with("\\end{") {
                    let cmd_len = if rest.starts_with("\\begin{") { 7 } else { 5 };
                    i += cmd_len;
                    // Skip past the env name and closing }
                    while i < len && bytes[i] != b'}' {
                        i += 1;
                    }
                    if i < len {
                        i += 1; // skip }
                    }
                    continue;
                } else {
                    i += 1;
                }
            }
            b'{' => {
                running += 1;
                i += 1;
            }
            b'}' => {
                running -= 1;
                if running < min_running {
                    min_running = running;
                }
                i += 1;
            }
            b => {
                if b < 0x80 {
                    i += 1;
                } else {
                    // Multi-byte character
                    let ch_len = line[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
                    i += ch_len;
                }
            }
        }
    }

    (min_running, running)
}

// Count braces for a specific part of a line (after skipping the env command part)
fn count_braces_tex_from(line: &str, start: usize) -> (i32, i32) {
    if start >= line.len() {
        return (0, 0);
    }
    count_braces_tex(&line[start..])
}

// For BibTeX: simple brace counting (no \begin/\end special cases)
fn count_braces_bib(line: &str) -> (i32, i32) {
    let mut running = 0i32;
    let mut min_running = 0i32;

    for ch in line.chars() {
        match ch {
            '%' => break,
            '{' => {
                running += 1;
            }
            '}' => {
                running -= 1;
                if running < min_running {
                    min_running = running;
                }
            }
            _ => {}
        }
    }

    (min_running, running)
}

// ===== INDENT STATE =====

struct IndentState {
    actual: i32,
    file_type: FileType,
    lists: Vec<String>,
    no_indent_envs: Vec<String>,
    verbatims: Vec<String>,
    in_verbatim: bool,
    verbatim_env: String,
}

impl IndentState {
    fn new(file_type: FileType, lists: Vec<String>, no_indent_envs: Vec<String>, verbatims: Vec<String>) -> Self {
        IndentState {
            actual: 0,
            file_type,
            lists,
            no_indent_envs,
            verbatims,
            in_verbatim: false,
            verbatim_env: String::new(),
        }
    }

    fn env_delta(&self, env_name: &str) -> i32 {
        if self.no_indent_envs.iter().any(|e| e == env_name) {
            0
        } else if self.lists.iter().any(|e| e == env_name) {
            2
        } else {
            1
        }
    }

    fn is_verbatim_env(&self, env_name: &str) -> bool {
        self.verbatims.iter().any(|e| e == env_name)
    }
}

// Process a single (stripped) line and compute visual indent
// Also updates state.actual
fn compute_indent(stripped_line: &str, state: &mut IndentState) -> i32 {
    if stripped_line.is_empty() {
        return state.actual;
    }

    match state.file_type {
        FileType::Tex => compute_indent_tex(stripped_line, state),
        FileType::Bib => compute_indent_bib(stripped_line, state),
    }
}

fn compute_indent_tex(line: &str, state: &mut IndentState) -> i32 {
    // Check for \end{envname}
    if line.starts_with("\\end{") {
        if let Some(env_name) = get_env_name(line) {
            let delta = state.env_delta(env_name);
            state.actual -= delta;
            // Clamp to -1 for error tracking, but don't go below -1 in display

            let visual = state.actual;

            // Count extra braces AFTER \end{envname}
            let skip = 5 + env_name.len() + 1; // \end{ + name + }
            let (min_r, net) = count_braces_tex_from(line, skip);
            state.actual += net;

            // Adjust visual based on close braces
            let visual_adj = std::cmp::min(0i32, min_r);
            return visual + visual_adj;
        }
    }

    // Check for \begin{envname}
    if line.starts_with("\\begin{") {
        if let Some(env_name) = get_env_name(line) {
            let visual = state.actual;
            let delta = state.env_delta(env_name);
            state.actual += delta;

            // Count extra braces AFTER \begin{envname}
            let skip = 7 + env_name.len() + 1; // \begin{ + name + }
            let (min_r, net) = count_braces_tex_from(line, skip);
            state.actual += net;

            let visual_adj = std::cmp::min(0i32, min_r);
            return visual + visual_adj;
        }
    }

    // Check for \item
    if is_item_token(line) {
        let visual = std::cmp::max(0, state.actual - 1);

        // Count braces on the \item line (excluding the command itself)
        // The \item line: count all braces
        let (min_r, net) = count_braces_tex(line);
        state.actual += net;

        let visual_adj = std::cmp::min(0i32, min_r);
        return visual + visual_adj;
    }

    // Regular line
    let (min_r, net) = count_braces_tex(line);
    let visual_adj = std::cmp::min(0i32, min_r);
    let visual = state.actual + visual_adj;
    state.actual += net;
    visual
}

fn compute_indent_bib(line: &str, state: &mut IndentState) -> i32 {
    let (min_r, net) = count_braces_bib(line);
    let visual_adj = std::cmp::min(0i32, min_r);
    let visual = state.actual + visual_adj;
    state.actual += net;
    visual
}

// ===== INDENTATION HELPERS =====

fn make_indent(visual: i32, tabsize: usize, usetabs: bool) -> String {
    if visual <= 0 {
        return String::new();
    }
    let n = (visual as usize) * tabsize;
    if usetabs {
        "\t".repeat(n)
    } else {
        " ".repeat(n)
    }
}

// ===== WRAPPING =====

// Find wrap point: returns byte index of the character to split at
// For a space: returns the byte index of the space (first part = line[..idx], second = line[idx+1..])
// For a wrap_char: returns byte index of char (first part = line[..idx + char_len], second = line[idx + char_len..])
fn find_wrap_split(line: &str, wraplen: usize, wrapmin: usize, wrap_chars: &[String]) -> Option<(usize, bool)> {
    // Returns (byte_index, is_space_type)
    // For space: first_part = line[..byte_index], split after the space
    // For wrap_char: first_part includes the char, split after it

    let chars: Vec<char> = line.chars().collect();
    let char_count = chars.len();

    if char_count <= wraplen {
        return None;
    }

    // Build byte positions
    let mut byte_positions: Vec<usize> = Vec::with_capacity(char_count + 1);
    let mut byte_pos = 0;
    for ch in &chars {
        byte_positions.push(byte_pos);
        byte_pos += ch.len_utf8();
    }
    byte_positions.push(byte_pos);

    // Find wrap points:
    // - Space at char index i: first_part_char_count = i, wrapped at space
    // - Wrap_char at char index i: first_part_char_count = i + 1, wrapped after char

    let mut last_below_wrapmin: Option<(usize, bool)> = None;
    let mut first_in_range: Option<(usize, bool)> = None;

    for i in 0..char_count {
        let ch = chars[i];
        let is_space = ch == ' ';
        let ch_str: String = ch.to_string();
        let is_wrap_char = !is_space && wrap_chars.iter().any(|wc| *wc == ch_str);

        if is_space || is_wrap_char {
            let first_part_len = if is_space { i } else { i + 1 };

            if first_part_len < wrapmin {
                last_below_wrapmin = Some((i, is_space));
            } else if first_part_len >= wrapmin && first_part_len <= wraplen {
                if first_in_range.is_none() {
                    first_in_range = Some((i, is_space));
                }
            }
            // If > wraplen: beyond wrap point, stop considering
        }
    }

    if let Some((char_idx, is_space)) = last_below_wrapmin {
        Some((byte_positions[char_idx], is_space))
    } else if let Some((char_idx, is_space)) = first_in_range {
        Some((byte_positions[char_idx], is_space))
    } else {
        None
    }
}

// Wrap a line, returning (first_part, second_part_content_without_indent)
// The second part is just the content after the wrap point (no indentation)
fn wrap_line_once(line: &str, wraplen: usize, wrapmin: usize, wrap_chars: &[String]) -> Option<(String, String)> {
    if line.chars().count() <= wraplen {
        return None;
    }

    if let Some((byte_idx, is_space)) = find_wrap_split(line, wraplen, wrapmin, wrap_chars) {
        if is_space {
            // Split at space: first = line[..byte_idx], second = line[byte_idx+1..]
            let first = line[..byte_idx].to_string();
            let second_start = byte_idx + 1;
            if second_start >= line.len() {
                return None;
            }
            let second = line[second_start..].to_string();
            Some((first, second))
        } else {
            // Wrap char: first includes the char, second starts after
            let ch_len = line[byte_idx..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
            let first_end = byte_idx + ch_len;
            let first = line[..first_end].to_string();
            let second = if first_end < line.len() {
                line[first_end..].to_string()
            } else {
                String::new()
            };
            Some((first, second))
        }
    } else {
        None
    }
}

// ===== MAIN FORMATTING =====

struct LineInfo {
    content: String,   // formatted line content (with indentation, trimmed of trailing whitespace)
    visual: i32,
    source_line: usize, // 1-indexed source line number
}

fn format_content(
    content: &str,
    filename: &str,
    cfg: &Config,
    file_type: FileType,
) -> (String, bool) {
    let verbosity = &cfg.verbosity;

    log_info(verbosity, filename, "Formatting started.");

    let lines: Vec<&str> = content.lines().collect();

    let mut state = IndentState::new(
        file_type,
        cfg.lists.clone(),
        cfg.no_indent_envs.clone(),
        cfg.verbatims.clone(),
    );

    let mut output_lines: Vec<String> = Vec::new();
    let mut output_line_num = 1usize;

    // Warnings tracking
    let mut last_nonindented_line: Option<usize> = None;
    let mut first_negative_line: Option<usize> = None;

    // Queue for processing: (content, source_line_1indexed)
    let mut line_queue: VecDeque<(String, usize)> = VecDeque::new();

    for (idx, &line) in lines.iter().enumerate() {
        line_queue.push_back((line.trim_end().to_string(), idx + 1));
    }

    while let Some((line, source_line)) = line_queue.pop_front() {
        // Handle verbatim mode
        if state.in_verbatim {
            let stripped = line.trim_start();
            let end_pattern = format!("\\end{{{}}}", state.verbatim_env);
            if stripped.starts_with(&end_pattern) {
                state.in_verbatim = false;
                state.verbatim_env.clear();
            }
            output_lines.push(line.trim_end().to_string());
            output_line_num += 1;
            continue;
        }

        let stripped = line.trim_start();

        // Check for verbatim begin
        if stripped.starts_with("\\begin{") {
            if let Some(env_name) = get_env_name(stripped) {
                if state.is_verbatim_env(env_name) {
                    state.in_verbatim = true;
                    state.verbatim_env = env_name.to_string();
                    // Output as-is
                    output_lines.push(line.trim_end().to_string());
                    output_line_num += 1;
                    continue;
                }
            }
        }

        // Check for env splitting
        if needs_env_split(stripped) {
            log_trace(verbosity, filename, &format!(
                "Line {} ({}). Placing environment on new line. {}",
                output_line_num, source_line, stripped
            ));
            let (first, second) = split_env_line(stripped);
            // Push second to front, then first (so first gets processed next)
            if !second.is_empty() {
                line_queue.push_front((second, source_line));
            }
            line_queue.push_front((first, source_line));
            continue;
        }

        // Compute indent
        let visual = compute_indent(stripped, &mut state);
        let actual = state.actual;

        // Build indented line
        let indent_str = make_indent(visual, cfg.tabsize, cfg.usetabs);
        let full_line = if stripped.is_empty() {
            String::new()
        } else {
            format!("{}{}", indent_str, stripped)
        };

        // Trace the line (before wrapping)
        log_trace(verbosity, filename, &format!(
            "Line {} ({}). Indent: actual = {}, visual = {}: {}",
            output_line_num, source_line, actual, visual, stripped
        ));

        // Warn on negative indent
        if visual < 0 || actual < 0 {
            log_warn(verbosity, filename, &format!(
                "Line {} ({}). Indent is negative. {}",
                output_line_num, source_line, stripped
            ));
            if first_negative_line.is_none() {
                first_negative_line = Some(source_line);
            }
        }

        // Track last non-indented line
        if visual == 0 && !stripped.is_empty() {
            last_nonindented_line = Some(source_line);
        }

        // Apply wrapping
        if cfg.wrap && !full_line.is_empty() && full_line.chars().count() > cfg.wraplen {
            log_trace(verbosity, filename, &format!(
                "Line {} ({}). Wrapping long line. {}",
                output_line_num, source_line, stripped
            ));

            // Wrap recursively
            let wrap_result = do_wrap(
                &full_line, 
                visual, 
                actual,
                cfg.wraplen, 
                cfg.wrapmin,
                &cfg.wrap_chars,
                cfg.tabsize,
                cfg.usetabs,
            );

            if wrap_result.len() == 1 {
                // No wrap happened - warn
                let first_content = &wrap_result[0].0.trim_start().to_string();
                if wrap_result[0].0.chars().count() > cfg.wraplen {
                    log_warn(verbosity, filename, &format!(
                        "Line {} ({}). Line cannot be wrapped. {}",
                        output_line_num, source_line, stripped
                    ));
                }
                // Log and output the first part
                let line_content = wrap_result[0].0.trim_start().to_string();
                log_trace(verbosity, filename, &format!(
                    "Line {} ({}). Indent: actual = {}, visual = {}: {}",
                    output_line_num, source_line, actual, visual, line_content
                ));
                output_lines.push(wrap_result[0].0.trim_end().to_string());
                output_line_num += 1;
            } else {
                for (part_idx, (part_line, part_visual)) in wrap_result.iter().enumerate() {
                    let part_content = part_line.trim_start().to_string();
                    let part_trimmed = part_line.trim_end().to_string();
                    log_trace(verbosity, filename, &format!(
                        "Line {} ({}). Indent: actual = {}, visual = {}: {}",
                        output_line_num, source_line, actual, part_visual, part_content
                    ));
                    output_lines.push(part_trimmed);
                    output_line_num += 1;
                }
            }
        } else {
            output_lines.push(full_line.trim_end().to_string());
            output_line_num += 1;
        }
    }

    // Post-process warnings
    if state.actual != 0 {
        if let Some(last_line) = last_nonindented_line {
            log_warn(verbosity, filename, &format!(
                "Indent does not return to zero. Last non-indented line is line {}",
                last_line
            ));
        }
    }

    if let Some(neg_line) = first_negative_line {
        log_warn(verbosity, filename, &format!(
            "Negative indents. First negatively indented line is line {}",
            neg_line
        ));
    }

    log_info(verbosity, filename, "Formatting complete.");

    // Join lines
    let mut result = output_lines.join("\n");
    if !result.is_empty() {
        result.push('\n');
    } else if !content.is_empty() {
        result.push('\n');
    }

    let changed = result != content;
    (result, changed)
}

// Wrap a fully-indented line recursively
// Returns vec of (indented_line_content, visual) pairs
fn do_wrap(
    line: &str,
    visual: i32,
    actual: i32,
    wraplen: usize,
    wrapmin: usize,
    wrap_chars: &[String],
    tabsize: usize,
    usetabs: bool,
) -> Vec<(String, i32)> {
    if line.chars().count() <= wraplen {
        return vec![(line.to_string(), visual)];
    }

    if let Some((first, second_content)) = wrap_line_once(line, wraplen, wrapmin, wrap_chars) {
        let first_trimmed = first.trim_end().to_string();

        // Second part gets indented at 'actual' level
        let new_indent = make_indent(actual, tabsize, usetabs);
        let second_line = format!("{}{}", new_indent, second_content.trim_start());

        let mut result = vec![(first_trimmed, visual)];

        // Recursively wrap second part
        let mut more = do_wrap(&second_line, actual, actual, wraplen, wrapmin, wrap_chars, tabsize, usetabs);
        result.append(&mut more);
        result
    } else {
        vec![(line.to_string(), visual)]
    }
}

// ===== FILE PROCESSING =====

fn process_file(path: &str, cfg: &Config) -> i32 {
    let file_type = match get_file_type(path) {
        Some(ft) => ft,
        None => {
            log_error(&cfg.verbosity, path, "File type invalid.");
            return 1;
        }
    };

    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => {
            log_error(&cfg.verbosity, path, "Could not open file.");
            return 1;
        }
    };

    let (formatted, changed) = format_content(&content, path, cfg, file_type);

    if cfg.check {
        if changed {
            log_error(&cfg.verbosity, path, "Incorrect formatting.");
            return 1;
        }
    } else if cfg.print {
        print!("{}", formatted);
    } else {
        if changed {
            if let Err(_) = fs::write(path, &formatted) {
                log_error(&cfg.verbosity, path, "Could not write file.");
                return 1;
            }
        }
        if cfg.fail_on_change && changed {
            return 1;
        }
    }

    0
}

fn process_stdin(cfg: &Config) -> i32 {
    let mut content = String::new();
    match io::stdin().read_to_string(&mut content) {
        Ok(n) => {
            log_trace(&cfg.verbosity, "<stdin>", &format!("Read {} bytes.", n));
        }
        Err(_) => {
            log_error(&cfg.verbosity, "<stdin>", "Could not read stdin.");
            return 1;
        }
    }

    let (formatted, _) = format_content(&content, "<stdin>", cfg, FileType::Tex);
    print!("{}", formatted);
    0
}

fn collect_files_recursive(dir: &str, files: &mut Vec<String>) {
    let path = Path::new(dir);
    if path.is_file() {
        let s = path.to_string_lossy().to_string();
        if get_file_type(&s).is_some() {
            files.push(s);
        }
        return;
    }

    if let Ok(entries) = fs::read_dir(path) {
        let mut sorted: Vec<_> = entries.filter_map(|e| e.ok()).collect();
        sorted.sort_by_key(|e| e.path());

        for entry in sorted {
            let p = entry.path();
            let s = p.to_string_lossy().to_string();
            if p.is_dir() {
                collect_files_recursive(&s, files);
            } else if p.is_file() && get_file_type(&s).is_some() {
                files.push(s);
            }
        }
    }
}

