fn print_completion(shell: &str) {
    match shell {
        "bash" => print_bash_completion(),
        "zsh" => print_zsh_completion(),
        "fish" => print_fish_completion(),
        "elvish" => print_elvish_completion(),
        "powershell" => print_powershell_completion(),
        _ => {}
    }
}

fn print_bash_completion() {
    print!(r#"_tex-fmt() {{
    local i cur prev opts cmd
    COMPREPLY=()
    if [[ "${{BASH_VERSINFO[0]}}" -ge 4 ]]; then
        cur="$2"
    else
        cur="${{COMP_WORDS[COMP_CWORD]}}"
    fi
    prev="$3"
    cmd=""
    opts=""

    for i in "${{COMP_WORDS[@]:0:COMP_CWORD}}"
    do
        case "${{cmd}},${{i}}" in
            ",$1")
                cmd="tex__fmt"
                ;;
            *)
                ;;
        esac
    done

    case "${{cmd}}" in
        tex__fmt)
            opts="-c -p -f -n -l -t -s -v -q -r -h -V --check --print --fail-on-change --nowrap --wraplen --tabsize --usetabs --stdin --config --noconfig --verbose --quiet --trace --completion --man --args --recursive --help --version [files]..."
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            case "${{prev}}" in
                --wraplen)
                    COMPREPLY=($(compgen -f "${{cur}}"))
                    return 0
                    ;;
                -l)
                    COMPREPLY=($(compgen -f "${{cur}}"))
                    return 0
                    ;;
                --tabsize)
                    COMPREPLY=($(compgen -f "${{cur}}"))
                    return 0
                    ;;
                -t)
                    COMPREPLY=($(compgen -f "${{cur}}"))
                    return 0
                    ;;
                --config)
                    COMPREPLY=($(compgen -f "${{cur}}"))
                    return 0
                    ;;
                --completion)
                    COMPREPLY=($(compgen -W "bash elvish fish powershell zsh" -- "${{cur}}"))
                    return 0
                    ;;
                *)
                    COMPREPLY=($(compgen -f "${{cur}}"))
                    return 0
                    ;;
            esac
            ;;
    esac
}}

complete -F _tex-fmt -o nosort -o bashdefault -o default tex-fmt
"#);
}

