fn print_args(cfg: &Config) {
    // Determine effective values for display
    let effective_print = cfg.print || cfg.stdin;
    let effective_foc = cfg.fail_on_change || cfg.print || cfg.stdin;

    let pad = "                           "; // 27 spaces to align values

    println!("tex-fmt");
    println!("  check:                   {}", cfg.check);
    println!("  print:                   {}", effective_print);
    println!("  fail-on-change:          {}", effective_foc);
    println!("  wrap:                    {}", cfg.wrap);
    println!("  wraplen:                 {}", cfg.wraplen);
    println!("  wrapmin:                 {}", cfg.wrapmin);
    println!("  tabsize:                 {}", cfg.tabsize);
    println!("  tabchar:                 {}", if cfg.usetabs { "tab" } else { "space" });
    println!("  stdin:                   {}", cfg.stdin);
    println!("  config:                  {}", cfg.config_path.as_deref().unwrap_or("None"));
    println!("  verbosity:               {}", match cfg.verbosity {
        Verbosity::Error => "error",
        Verbosity::Warn => "warn",
        Verbosity::Info => "info",
        Verbosity::Trace => "trace",
    });

    // Print lists
    if let Some(first) = cfg.lists.first() {
        println!("  lists:                   {}", first);
        for item in cfg.lists.iter().skip(1) {
            println!("{}{}", pad, item);
        }
    }

    // Print verbatims
    if let Some(first) = cfg.verbatims.first() {
        println!("  verbatims:               {}", first);
        for item in cfg.verbatims.iter().skip(1) {
            println!("{}{}", pad, item);
        }
    }

    // Print no-indent-envs
    if let Some(first) = cfg.no_indent_envs.first() {
        println!("  no-indent-envs:          {}", first);
        for item in cfg.no_indent_envs.iter().skip(1) {
            println!("{}{}", pad, item);
        }
    }

    // Print wrap-chars
    if cfg.wrap_chars.is_empty() {
        println!("  wrap-chars:               ");
    } else {
        if let Some(first) = cfg.wrap_chars.first() {
            println!("  wrap-chars:              {}", first);
        }
        for item in cfg.wrap_chars.iter().skip(1) {
            println!("{}{}", pad, item);
        }
        // Trailing space entry (observed behavior)
        println!("{}  ", pad);
    }

    // Print files (only if not stdin mode)
    if !cfg.stdin {
        for f in &cfg.files {
            println!("  files:                   {}", f);
        }
    }
}

// ===== MAIN =====

fn main() {
    let cfg = parse_args();
    let mut exit_code = 0;

    if cfg.stdin {
        exit_code = process_stdin(&cfg);
    } else if cfg.recursive {
        let mut all_files: Vec<String> = Vec::new();

        if cfg.files.is_empty() {
            collect_files_recursive(".", &mut all_files);
        } else {
            for f in &cfg.files {
                collect_files_recursive(f, &mut all_files);
            }
        }

        for file in &all_files {
            let r = process_file(file, &cfg);
            if r != 0 {
                exit_code = r;
            }
        }
    } else if cfg.files.is_empty() {
        log_error(&cfg.verbosity, "", "No files specified. Provide filenames, or pass --recursive or --stdin.");
        exit_code = 1;
    } else {
