\int_0^\infty f(x) e^{-x} \,dx = \sum_{n=0}^\infty \frac{(-1)^n}{n!} f^{(n)}(0)
\end{equation}
\begin{theorem}
If $f$ satisfies the following conditions:
\begin{itemize}
\item $f$ is continuous on $[0, \infty)$
\item $f$ is bounded by an exponential function
\item The integral converges absolutely
\end{itemize}
then the equation holds.
\end{theorem}
\begin{proof}
We proceed by induction.
\begin{enumerate}
\item Base case: $n = 0$
\item Inductive step: Assume the result holds for $n = k$.
Then for $n = k + 1$:
\begin{align}
\int_0^\infty f(x) e^{-x} \,dx &= \int_0^\infty f(x) e^{-x} \,dx \\
&= \sum_{n=0}^k \frac{(-1)^n}{n!} f^{(n)}(0) + R_k
\end{align}
\end{enumerate}
\end{proof}
\end{document}
